 private Object field(String name)throws Exception{Field f=NativeActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}private void set(String name,Object value)throws Exception{Field f=NativeActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(activity,value);}
