 private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);report.append("PASS ").append(message).append('\n');}
 private interface Condition{boolean ok()throws Exception;}private void await(Condition condition,String name)throws Exception{long due=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<due){AtomicBoolean ok=new AtomicBoolean();AtomicReference<Exception> error=new AtomicReference<>();main(()->{try{ok.set(condition.ok());}catch(Exception e){error.set(e);}});if(error.get()!=null)throw error.get();if(ok.get())return;SystemClock.sleep(150);}throw new AssertionError("Timed out: "+name);}
 private JSONObject last()throws Exception{JSONObject state=(JSONObject)field("state");JSONArray messages=state.getJSONArray("chats").getJSONObject(0).getJSONArray("messages");return messages.getJSONObject(messages.length()-1);}
 private void send(String value){main(()->{try{((EditText)field("input")).setText(value);((Button)field("send")).performClick();}catch(Exception e){throw new RuntimeException(e);}});}
 private String visible(View view){String value=view instanceof TextView?((TextView)view).getText().toString()+"\n":"";if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)value+=visible(((ViewGroup)view).getChildAt(i));return value;}
 private void shot(String name){SystemClock.sleep(300);Bitmap b=getUiAutomation().takeScreenshot();ByteArrayOutputStream bytes=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,bytes);b.recycle();Bundle out=new Bundle();out.putString("screen_"+name,android.util.Base64.encodeToString(bytes.toByteArray(),android.util.Base64.NO_WRAP));sendStatus(1,out);}
 public static final class MockConnection extends HttpsURLConnection {
  private final ByteArrayOutputStream sent=new ByteArrayOutputStream();private InputStream input;private int ordinal;MockConnection(URL url){super(url);}public void connect(){}public void disconnect(){try{if(input!=null)input.close();}catch(Exception ignored){}}public boolean usingProxy(){return false;}public OutputStream getOutputStream(){return sent;}public InputStream getErrorStream(){return new ByteArrayInputStream("invalid API key".getBytes());}public int getResponseCode(){if("Bearer sk-invalid-test".equals(getRequestProperty("Authorization")))return 401;if(url.getPath().equals("/chat/completions")){ordinal=requests.incrementAndGet();payloads.add(new String(sent.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));}return 200;}public String getContentType(){return url.getPath().equals("/chat/completions")?"text/event-stream":"application/json";}
  public InputStream getInputStream()throws IOException{if(input!=null)return input;if(url.getPath().equals("/user/balance"))return new ByteArrayInputStream("{\"is_available\":true,\"balance_infos\":[{\"currency\":\"CNY\",\"total_balance\":\"12.34\",\"granted_balance\":\"2.00\",\"topped_up_balance\":\"10.34\"}]}".getBytes("UTF-8"));final PipedOutputStream out=new PipedOutputStream();input=new PipedInputStream(out,65536);final int number=ordinal;final boolean fail=failNext;failNext=false;Thread stream=new Thread(()->{try{if(number==1){Thread.sleep(600);frame(out,"reasoning_content","先梳理这个问题。");Thread.sleep(600);frame(out,"content","保留下来的第一段。");Thread.sleep(4500);frame(out,"content","重建后继续收到的第二段。");}else if(fail){Thread.sleep(300);frame(out,"content","中断前保留的内容。");Thread.sleep(400);return;}else{Thread.sleep(400);frame(out,"content","这是手动续写的新内容。");}out.write("data: {\"choices\":[{\"delta\":{},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n".getBytes("UTF-8"));out.flush();}catch(Exception ignored){}finally{try{out.close();}catch(Exception ignored){}}});stream.setDaemon(true);stream.start();return input;}
  private void frame(OutputStream out,String key,String value)throws Exception{String frame="data: "+new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("delta",new JSONObject().put(key,value)))).toString()+"\n\n";out.write(frame.getBytes("UTF-8"));out.flush();}
  public String getCipherSuite(){return "TEST";}public Certificate[] getLocalCertificates(){return null;}public Certificate[] getServerCertificates(){return null;}public Principal getPeerPrincipal(){return null;}public Principal getLocalPrincipal(){return null;}
 }
